const FAQS =
  '<!doctype html>\n\n<html lang="en">\n  <head>\n    <meta charset="utf-8" />\n    <meta\n      content="form-action \'none\'; connect-src \'none\'; frame-src \'none\'; object-src \'none\'; base-uri \'none\'"\n      http-equiv="Content-Security-Policy"\n    />\n    <meta content="width=device-width,initial-scale=1" name="viewport" />\n    <meta content="noindex,nofollow" name="robots" />\n    <meta\n      content="FAQs about local FirstLight home care, pricing, caregivers and getting started."\n      name="description"\n    />\n    <title>FAQs | FirstLight Home Care | Southern California</title>\n    <link href="assets/faqs.css" rel="stylesheet" />\n  </head>\n  <body class="guided faq-reference">\n    <a class="skip" href="#main">Skip to content</a>\n    <header class="header">\n      <div class="wrap header-inner">\n        <a\n          aria-label="FirstLight Home Care: Southern California"\n          class="brand"\n          href="index.html"\n          ><img\n            alt="FirstLight Home Care"\n            height="136"\n            src="data:image/png;base64,"\n            width="484"\n          /><span class="region">Southern<br />California</span></a\n        >\n        <div class="nav-toggle-wrap">\n          <input\n            aria-controls="site-nav"\n            class="nav-toggle-input"\n            id="nav-toggle"\n            type="checkbox"\n          />\n          <label class="nav-toggle" for="nav-toggle">\n            <span aria-hidden="true" class="nav-toggle-icon"></span>\n            <span class="when-closed">Menu</span>\n            <span class="when-open">Close</span>\n          </label>\n        </div>\n        <nav aria-label="Main navigation" class="nav" id="site-nav">\n          <a data-go-step="1" href="index.html#guided-flow">Start the guide</a\n          ><a href="locations.html">About us</a\n          ><a href="services.html">Services</a\n          ><a aria-current="page" href="faqs.html">FAQs</a>\n        </nav>\n      </div>\n    </header>\n    <main id="main" tabindex="-1">\n      <section aria-labelledby="faq-title" class="section faq" id="care-faq">\n        <div class="wrap faq-layout">\n          <div class="faq-intro">\n            <p class="eyebrow">Helpful answers</p>\n            <h1 id="faq-title">FAQs</h1>\n            <p>\n              Here are the practical questions to bring to your local team. Each\n              office is independently owned, so rates, availability and\n              agreement terms need a local answer.\n            </p>\n            <nav aria-label="On this page" class="faq-toc">\n              <p>On this page</p>\n              <ol>\n                <li><a href="#cat-billing">Cost, Billing &amp; Payment</a></li>\n                <li>\n                  <a href="#cat-caregivers">Caregivers &amp; Care Quality</a>\n                </li>\n                <li>\n                  <a href="#cat-services">Services &amp; Care Boundaries</a>\n                </li>\n                <li>\n                  <a href="#cat-getting-started"\n                    >Getting Started &amp; Privacy</a\n                  >\n                </li>\n              </ol>\n            </nav>\n            <a class="button faq-start" href="index.html#guided-flow"\n              >Start the care guide</a\n            >\n          </div>\n          <div class="faq-column">\n            <div class="faq-tools" hidden="" id="faq-tools">\n              <span class="placeholder-tag"\n                >Placeholder: future AI assistant</span\n              ><label for="faq-search">Find a relevant question</label>\n              <p class="field-hint" id="faq-search-help">\n                No AI is connected. This demo matches keywords and similar words\n                in the FAQs on this page. Your search stays here.\n              </p>\n              <div class="faq-search-row">\n                <div class="faq-search-field">\n                  <svg aria-hidden="true" focusable="false" viewbox="0 0 24 24">\n                    <circle cx="10" cy="10" r="6"></circle>\n                    <path d="m15 15 6 6"></path></svg\n                  ><input\n                    aria-describedby="faq-search-help faq-search-status"\n                    autocomplete="off"\n                    id="faq-search"\n                    maxlength="100"\n                    placeholder="Try pricing or same caregiver"\n                    type="search"\n                  />\n                </div>\n                <button\n                  class="quiet-button"\n                  hidden=""\n                  id="faq-search-clear"\n                  type="button"\n                >\n                  Clear search\n                </button>\n              </div>\n              <div class="faq-controls">\n                <button\n                  aria-controls="faq-list"\n                  class="quiet-button"\n                  id="faq-expand"\n                  type="button"\n                >\n                  Expand all</button\n                ><button\n                  aria-controls="faq-list"\n                  class="quiet-button"\n                  id="faq-collapse"\n                  type="button"\n                >\n                  Collapse all</button\n                ><span class="field-hint"\n                  >Applies to the matching questions.</span\n                >\n              </div>\n              <p\n                aria-atomic="true"\n                aria-live="polite"\n                class="faq-search-status"\n                id="faq-search-status"\n                role="status"\n              >\n                13 questions\n              </p>\n            </div>\n            <div class="faq-list" id="faq-list">\n              <div class="faq-category" data-category="billing">\n                <h2 id="cat-billing">Cost, Billing &amp; Payment</h2>\n                <span class="faq-category-line" aria-hidden="true"></span>\n              </div>\n              <details class="faq-item" id="faq-1">\n                <summary>What does home care cost?</summary>\n                <div class="faq-answer">\n                  <p id="pricing-wording">\n                    Rates vary by local office, the help needed and the\n                    schedule. Care is generally billed by the hour, and a\n                    minimum visit length may apply. Ask your local team for a\n                    written quote after a free care consultation, including any\n                    holiday, overtime, mileage and cancellation charges. There\n                    is no single Southern California alliance rate.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-2">\n                <summary>Is there a minimum number of hours?</summary>\n                <div class="faq-answer">\n                  <p>\n                    Minimums are set by each office and may depend on the\n                    service or schedule. Ask about the minimum per visit, any\n                    weekly commitment, and whether a shorter respite visit is\n                    possible. A minimum used by 1 office does not apply to every\n                    office on this page.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-3">\n                <summary>Does insurance or Medicare pay for care?</summary>\n                <div class="faq-answer">\n                  <p>\n                    Private pay is the most common way families pay for\n                    non-medical home care. Some services may be covered by\n                    long-term care insurance, veteran benefits, public programs\n                    or certain Medicare Advantage plans. Coverage, eligibility\n                    and participating providers vary.\n                  </p>\n                  <p>\n                    Ask your office to review your options, and confirm approval\n                    and any out-of-pocket costs with your insurer or benefit\n                    program before care starts. Do not assume a health insurance\n                    card means these services are covered.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-4">\n                <summary>\n                  Are there benefits for veterans or surviving spouses?\n                </summary>\n                <div class="faq-answer">\n                  <p>\n                    Eligible veterans may have options through VA Home and\n                    Community Based Services. Aid &amp; Attendance may help\n                    eligible veterans and surviving spouses who need help with\n                    daily activities. Not everyone qualifies, and not every\n                    office participates in every program.\n                  </p>\n                  <p>\n                    Your local team can discuss available options. The VA or the\n                    relevant benefit program determines eligibility and\n                    authorization; this page cannot promise approval or a\n                    covered number of hours.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-9">\n                <summary>\n                  Do we sign a contract? How do changes or cancellations work?\n                </summary>\n                <div class="faq-answer">\n                  <p>\n                    A written client service agreement sets the schedule, rates,\n                    billing and other terms. Cancellation notice, possible fees,\n                    schedule changes and termination terms must be confirmed\n                    with your own office before signing.\n                  </p>\n                  <p>\n                    Do not assume there is no contract, no minimum commitment or\n                    free last-minute cancellation. Your local team should\n                    explain these terms and provide them in writing before care\n                    starts.\n                  </p>\n                </div>\n              </details>\n              <div class="faq-category" data-category="caregivers">\n                <h2 id="cat-caregivers">Caregivers &amp; Care Quality</h2>\n                <span class="faq-category-line" aria-hidden="true"></span>\n              </div>\n              <details class="faq-item" id="faq-6">\n                <summary>How are caregivers screened and trained?</summary>\n                <div class="faq-answer">\n                  <p>\n                    FirstLight describes its caregivers as direct employees, not\n                    independent contractors, who undergo screening, background\n                    checks and care training. Matches consider experience,\n                    availability and personality.\n                  </p>\n                  <p>\n                    Ask your office which checks and training apply to the\n                    person supporting you, especially for dementia, mobility or\n                    other specific needs.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-7">\n                <summary>Can we have the same caregiver each time?</summary>\n                <div class="faq-answer">\n                  <p>\n                    FirstLight matches caregivers to the client’s needs,\n                    schedule and personality. Tell your team what helps you or\n                    your loved one feel comfortable, and ask about a regular\n                    caregiver or small team.\n                  </p>\n                  <p>\n                    Continuity depends on scheduling and availability. A\n                    substitution may sometimes be needed, so ask how changes are\n                    handled rather than assuming the same person will cover\n                    every visit.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-8">\n                <summary>\n                  What happens if our caregiver is sick or unavailable?\n                </summary>\n                <div class="faq-answer">\n                  <p>\n                    Contact the office, which manages scheduling and caregiver\n                    substitutions. Ask in advance how it handles a missed shift,\n                    how you will be notified and which number to use after\n                    hours.\n                  </p>\n                  <p>\n                    Backup arrangements vary by office and schedule;\n                    uninterrupted coverage should not be assumed. Agree on a\n                    backup plan with your family and the office before care\n                    begins.\n                  </p>\n                </div>\n              </details>\n              <div class="faq-category" data-category="services">\n                <h2 id="cat-services">Services &amp; Care Boundaries</h2>\n                <span class="faq-category-line" aria-hidden="true"></span>\n              </div>\n              <details class="faq-item" id="faq-10">\n                <summary>\n                  Is this medical care? Can a caregiver manage medications?\n                </summary>\n                <div class="faq-answer">\n                  <p>\n                    This page describes non-medical support with everyday\n                    living. Medication reminders are different from prescribing,\n                    changing doses or providing medical treatment. Nursing,\n                    wound care, injections and therapy need an appropriately\n                    licensed provider.\n                  </p>\n                  <p>\n                    The local team should explain what is allowed in your care\n                    plan and whether another provider is needed. Call 911 for an\n                    emergency.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-12">\n                <summary>\n                  Do we need to choose a service before calling?\n                </summary>\n                <div class="faq-answer">\n                  <p>\n                    No. The names describe different kinds of help, and a care\n                    plan may combine them. You can explain what is happening at\n                    home in your own words. Your local team can help you work\n                    out the support, schedule and next steps.\n                  </p>\n                </div>\n              </details>\n              <div class="faq-category" data-category="getting-started">\n                <h2 id="cat-getting-started">Getting Started &amp; Privacy</h2>\n                <span class="faq-category-line" aria-hidden="true"></span>\n              </div>\n              <details class="faq-item" id="faq-5">\n                <summary>How quickly can care start?</summary>\n                <div class="faq-answer">\n                  <p>\n                    The team first listens to what you need, arranges an in-home\n                    visit, reviews the care plan and agreement, and confirms a\n                    start date and caregiver introduction. Timing depends on the\n                    care needed and local availability.\n                  </p>\n                  <p>\n                    Tell the office if a discharge or other date is approaching.\n                    There is no same-day or next-day start guarantee on this\n                    alliance page.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-11">\n                <summary>\n                  What should we have ready for the first conversation?\n                </summary>\n                <div class="faq-answer">\n                  <p>\n                    Start with where care is needed, what a usual day looks\n                    like, the tasks that are becoming difficult, and when help\n                    is needed. Share your priorities and the questions you want\n                    answered.\n                  </p>\n                  <p>\n                    For an assessment, the office may ask you to prepare a\n                    medication list, relevant insurance or long-term care\n                    information, and any healthcare decision-maker documents. Do\n                    not enter private health information on this page; there is\n                    no intake form here.\n                  </p>\n                </div>\n              </details>\n              <details class="faq-item" id="faq-location">\n                <summary>How does “Use my location” work?</summary>\n                <div class="faq-answer">\n                  <p>\n                    Nothing happens until you press the button and allow your\n                    browser to share your location. The guide compares it with\n                    approximate public addresses on your device. It does not\n                    send your coordinates anywhere or store them.\n                  </p>\n                  <p>\n                    Distance is straight-line, not a driving route or a\n                    confirmed service area. If 1 team is nearest, the guide\n                    continues without showing that team. If more than 1 team is\n                    equally near, you’ll be asked for a ZIP. Contact details\n                    appear at the last step. If you decline or location is\n                    unavailable, city or ZIP search still works.\n                  </p>\n                </div>\n              </details>\n            </div>\n            <div class="faq-no-results" hidden="" id="faq-no-results">\n              <h3>No matching questions.</h3>\n              <p>\n                Try pricing, minimum hours, insurance, same caregiver or start\n                date.\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n    </main>\n    <footer class="footer">\n      <div class="wrap footer-row">\n        <div>\n          <p class="disclaimer">\n            Draft. Each office is independently owned and operated. Not yet\n            approved by FirstLight Home Care corporate.\n          </p>\n          <p>\n            A proposed Southern California alliance page. Office details and ZIP\n            assignments require final owner confirmation before launch.\n          </p>\n        </div>\n        <div class="footer-links">\n          <a href="index.html#find-care">Start the guided flow ↑</a>\n        </div>\n      </div>\n      <div class="wrap">\n        <p class="geo-credit">\n          Approximate office-address coordinates: U.S. Census Geocoder and ©\n          <a\n            aria-label="OpenStreetMap contributors, data attribution (opens in a new tab)"\n            href="https://www.openstreetmap.org/copyright"\n            rel="noopener noreferrer"\n            target="_blank"\n            >OpenStreetMap contributors</a\n          >. Using your location does not confirm service territory.\n        </p>\n      </div>\n    </footer>\n    <script src="assets/nav.js"></script>\n    <script src="assets/faqs.js"></script>\n  </body>\n</html>\n';
